# ===== Zustand vs Pinia 代码量对比 =====

# Zustand（1个函数）
import { create } from 'zustand'

const useXxx = create((set, get) => ({
  value: 0,
  setValue: (v) => set({ value: v }),
  getValue: () => get().value
}))


# Pinia（1个函数）
import { defineStore } from 'pinia'

export const useXxx = defineStore('xxx', {
  state: () => ({ value: 0 }),
  getters: { doubleValue: (s) => s.value * 2 },
  actions: {
    setValue(v) { this.value = v }
  }
})


💡 Zustand：不区分 state/getters/actions（全平铺）
💡 Pinia： 分 state/getters/actions（结构清晰）
💡 选哪个？ 团队偏好 — 两者都非常成熟

# ===== Selector 的正确姿势 =====

import useCounterStore from '@/stores/counter'

function Counter() {
  // ❌ 错误：订阅了整个 Store
  // const store = useCounterStore()

  // ✅ 正确：只订阅需要的字段
  const count = useCounterStore((s) => s.count)
  const increment = useCounterStore((s) => s.increment)

  return (
    <div>
      <h2>Count: {count}</h2>
      <button onClick={increment}>+1</button>
    </div>
  )
}

# 也可以一个 selector 拿多个字段
const { count, name } = useCounterStore((s) => ({
  count: s.count,
  name: s.name
}))
# 默认用 Object.is 做浅比较


💡 用 selector 后，只 count 变化才重渲染
💡 如果只用了 increment（不变），组件永远不重渲染
💡 默认 Object.is 比较，可自定义 equality 函数

# ===== stores/user.js —— 异步 Actions =====

import { create } from 'zustand'

const useUserStore = create((set, get) => ({
  user: null,
  loading: false,
  error: null,

  // 同步 Action
  setUser: (user) => set({ user }),
  logout: () => set({ user: null }),

  // 异步 Action（直接 async/await）
  fetchUser: async (id) => {
    set({ loading: true, error: null })
    try {
      const res = await fetch(`/api/users/${id}`)
      const user = await res.json()
      set({ user, loading: false })
    } catch (e) {
      set({ error: e.message, loading: false })
    }
  },

  // Action 中使用 get() 读当前 state
  refreshUser: async () => {
    const { user } = get()
    if (user) {
      await useUserStore.getState().fetchUser(user.id)
    }
  }
}))


💡 async/await 直接用，不需要中间件
💡 get() 在 actions 中读取当前 state
💡 对比 Redux：省掉 thunk/saga + dispatch

