# ===== persist 中间件 —— 自动持久化 =====

import { create } from 'zustand'
import { persist } from 'zustand/middleware'

const useTodoStore = create(
  persist(
    (set) => ({
      todos: [],
      addTodo: (text) =>
        set((state) => ({
          todos: [...state.todos,
            { id: Date.now(), text, done: false }
          ]
        })),
      toggleTodo: (id) =>
        set((state) => ({
          todos: state.todos.map(t =>
            t.id === id ? { ...t, done: !t.done } : t
          )
        }))
    }),
    { name: 'todo-storage' }  // localStorage key
  )
)


# ===== devtools 中间件 —— 浏览器调试 =====
import { devtools } from 'zustand/middleware'

const useStore = create(
  devtools(
    (set) => ({
      count: 0,
      increment: () =>
        set((s) => ({ count: s.count + 1 }),
          false, 'increment')  // action name
    }),
    { name: 'MyStore' }  // DevTools 里显示的名字
  )
)


💡 persist → 自动同步 localStorage
💡 devtools → Redux DevTools 浏览器扩展
💡 immer → 复杂嵌套对象的不可变更新
💡 多个中间件可嵌套：devtools(persist(...))

# ===== stores/cart.js =====

import { create } from 'zustand'
import { persist } from 'zustand/middleware'

const useCartStore = create(
  persist(
    (set, get) => ({
      // State
      items: [
        { id: 1, name: 'React 教程', price: 99, qty: 1 },
        { id: 2, name: 'Zustand 指南', price: 79, qty: 2 }
      ],

      // Actions
      addItem: (item) =>
        set((state) => {
          const exist = state.items.find(i => i.id === item.id)
          if (exist) {
            return { items: state.items.map(i =>
              i.id === item.id
                ? { ...i, qty: i.qty + (item.qty || 1) }
                : i
            )}
          }
          return { items: [...state.items,
            { ...item, qty: item.qty || 1 }] }
        }),

      updateQty: (id, qty) =>
        set((state) => ({
          items: state.items.map(i =>
            i.id === id ? { ...i, qty } : i
          )
        })),

      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter(i => i.id !== id)
        })),

      clear: () => set({ items: [] }),

      // 计算（用 get 读）
      total: () =>
        get().items.reduce((s, i) => s + i.price * i.qty, 0),
      count: () =>
        get().items.reduce((s, i) => s + i.qty, 0)
    }),
    { name: 'cart-storage' }
  )
)

export default useCartStore


# ===== 组件中使用（CartPage.jsx） =====
import useCartStore from '@/stores/cart'

function CartPage() {
  const items = useCartStore((s) => s.items)
  const addItem = useCartStore((s) => s.addItem)
  const removeItem = useCartStore((s) => s.removeItem)
  const total = useCartStore().total()
  const count = useCartStore().count()

  return (<div>
    <h2>购物车 ({count})</h2>
    {items.map(item => (
      <div key={item.id}>
        <span>{item.name} ¥{item.price}</span>
        <span>×{item.qty}</span>
        <button onClick={() => removeItem(item.id)}>删除</button>
      </div>
    ))}
    <h3>总价: ¥{total}</h3>
  </div>)
}


💡 完整 Zustand 购物车 = create + set/get + persist + selector
💡 和 React 教程的组件无缝结合
